import {canWorkshop,canEditRecipes,canApproveRecipes,UNITS,scaleIngredients,recipePayload} from './workshop-model.js';

export function createWorkshop({db,root,state,guard,ready,render,notice,esc,dialogs}){
 let records=[],loaded=false,loading=false,error='',query='',filter='active',generation=0,currentOwner='',editing=null,loadedAt=0;
 const number=new Intl.NumberFormat('es-PE',{maximumFractionDigits:3});
 const allowed=()=>canWorkshop(state().me?.role);
 const editable=()=>canEditRecipes(state().me?.role);
 const approver=()=>canApproveRecipes(state().me?.role);
 const live=(owner,token)=>owner===state().user?.id&&token===generation&&ready()&&allowed();
 const label=r=>r.status==='approved'?'Validada':r.status==='archived'?'Archivada':'Provisional';
 const selected=id=>records.find(r=>r.id===id);
 const lines=r=>r.ingredients||[];
 const normalize=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 function visible(){const term=normalize(query);return records.filter(r=>(filter==='active'?r.status!=='archived':filter==='all'||r.status===filter)&&normalize(r.name+' '+lines(r).map(i=>i.name).join(' ')).includes(term));}
 function cards(){const list=visible();return list.length?list.map(r=>`<article class="recipe-card"><div class="recipe-card-top"><span class="recipe-tag ${esc(r.status)}">${label(r)}</span><span class="recipe-version">v${Number(r.version)}</span></div><h2>${esc(r.name)}</h2><div class="recipe-meta"><span>${lines(r).length} ingredientes</span><span>${r.yield_confirmed?`${number.format(r.output_qty)} ${esc(r.output_unit)} por tanda`:'Rendimiento por confirmar'}</span></div><button type="button" class="secondary" data-recipe-open="${esc(r.id)}">Ver receta</button></article>`).join(''):'<div class="recipe-empty">No se encontraron recetas.</div>';}
 function view(){if(!allowed())return '<div class="warn">No tienes acceso al taller.</div>';
  return `<section class="workshop-module"><div class="workshop-toolbar"><div class="workshop-scope">Almacén central del taller</div>${editable()?'<button type="button" data-recipe-new>+ Nueva receta</button>':''}</div>${error?`<div class="warn" role="alert">${esc(error)}</div>`:''}<div class="recipe-filters"><label class="recipe-search"><span class="sr-only">Buscar receta o ingrediente</span><input type="search" placeholder="Buscar receta o ingrediente" data-recipe-search value="${esc(query)}"></label><label><span class="sr-only">Estado</span><select data-recipe-filter><option value="active" ${filter==='active'?'selected':''}>Activas</option><option value="draft" ${filter==='draft'?'selected':''}>Provisionales</option><option value="approved" ${filter==='approved'?'selected':''}>Validadas</option><option value="archived" ${filter==='archived'?'selected':''}>Archivadas</option><option value="all" ${filter==='all'?'selected':''}>Todas</option></select></label></div><div class="recipe-grid" data-recipe-grid>${!loaded?'<p class="muted" role="status">Cargando recetas…</p>':cards()}</div></section>`;
 }
 async function refresh(){if(!allowed())throw Error('No tienes acceso al taller.');const owner=state().user?.id,token=generation;loading=true;try{
   await guard();const r=await db.rpc('charito_recipes_list');if(!live(owner,token))return;
   loaded=true;if(r.error){records=[];error=['PGRST202','42883'].includes(r.error.code)?'El administrador debe activar la actualización 22 de recetas en Supabase.':'No se pudieron cargar las recetas. Pulsa Actualizar.';return;}
   records=r.data||[];error='';currentOwner=owner;loadedAt=Date.now();
  }finally{loading=false;}}
 async function enter(view,force=false){if(view!=='recetas'||!allowed()||loading||!force&&loaded&&currentOwner===state().user?.id&&Date.now()-loadedAt<60000)return;const owner=state().user?.id,token=generation;
  try{await refresh();if(live(owner,token)&&state().view==='recetas'&&!dialogs.element)render();}catch(e){if(live(owner,token))notice(e.message,true);}}
 function detail(r){const items=lines(r);return `<div class="recipe-detail"><div class="recipe-detail-heading"><span class="recipe-tag ${esc(r.status)}">${label(r)}</span><span class="recipe-version">Versión ${Number(r.version)}</span></div>${r.status==='draft'?'<p class="recipe-draft-note">Cantidades propuestas pendientes de validación.</p>':''}<label class="recipe-batches">Tandas a preparar<input type="number" value="1" min="0.001" max="1000" step="0.001" inputmode="decimal" data-recipe-batches data-recipe-id="${esc(r.id)}"></label><div class="recipe-ingredients">${items.map((i,n)=>`<div class="recipe-ingredient"><div><strong>${esc(i.name)}</strong>${i.note?`<small>${esc(i.note)}</small>`:''}</div><div class="recipe-quantity"><strong data-scaled="${n}">${number.format(i.quantity)} ${esc(i.unit)}</strong><small>${i.confirmed?'Unidad confirmada':'Unidad por confirmar'}</small></div></div>`).join('')}</div><p class="recipe-calculation" data-recipe-calculation>Insumos para 1 tanda</p>${r.output_qty?`<div class="recipe-yield"><span>Rendimiento por tanda</span><strong>${number.format(r.output_qty)} ${esc(r.output_unit)}</strong>${r.yield_confirmed?'':'<small>Por confirmar</small>'}</div>`:''}${r.notes?`<div class="recipe-notes">${esc(r.notes)}</div>`:''}<div class="work-form-actions">${editable()&&r.status!=='archived'?`<button type="button" class="secondary" data-recipe-edit="${esc(r.id)}">Editar receta</button>`:''}${approver()&&r.status==='draft'?`<button type="button" data-recipe-approve="${esc(r.id)}">Validar receta</button>`:''}${approver()&&r.status!=='archived'?`<button type="button" class="secondary" data-recipe-archive="${esc(r.id)}">Archivar</button>`:''}</div></div>`;}
 function open(r){dialogs.open({key:'recipe-view',title:r.name,body:detail(r),wide:true,confirmDiscard:false});}
 function ingredient(i={name:'',quantity:'',unit:'g',confirmed:false,note:''}){return `<fieldset class="recipe-edit-line" data-recipe-line><div class="recipe-line-main"><label>Ingrediente<input data-ingredient-name value="${esc(i.name)}" maxlength="120" required></label><label>Cantidad<input type="number" data-ingredient-qty value="${esc(i.quantity)}" min="0.000001" max="1000000000" step="any" inputmode="decimal" required></label><label>Unidad<select data-ingredient-unit>${UNITS.map(u=>`<option ${u===i.unit?'selected':''}>${u}</option>`).join('')}</select></label><button type="button" class="secondary recipe-remove" data-recipe-remove aria-label="Quitar ingrediente">×</button></div><div class="recipe-line-bottom"><label class="check"><input type="checkbox" data-ingredient-confirmed ${i.confirmed?'checked':''}><span>Confirmado</span></label><label>Observación<input data-ingredient-note value="${esc(i.note)}" maxlength="400"></label></div></fieldset>`;}
 function editor(r){editing=r?.id||null;const value=r||{name:'',notes:'',output_qty:'',output_unit:'',yield_confirmed:false,ingredients:[{}]};dialogs.open({key:'recipe-edit',title:r?'Editar receta':'Nueva receta',wide:true,body:`<form data-form="recipe_save" data-id="${esc(r?.id||'')}" data-version="${Number(r?.version||0)}"><label>Nombre de la receta<input name="name" value="${esc(value.name)}" minlength="2" maxlength="120" required></label><div data-recipe-lines>${(value.ingredients||[]).map(ingredient).join('')}</div><button type="button" class="secondary" data-recipe-add>+ Agregar ingrediente</button><div class="recipe-output-fields"><label>Rendimiento por tanda<input name="output_qty" type="number" inputmode="decimal" min="0.000001" max="1000000000" step="any" value="${esc(value.output_qty??'')}"></label><label>Unidad o presentación<input name="output_unit" maxlength="80" value="${esc(value.output_unit)}" placeholder="Ej.: tortas de tamaño comercial"></label></div><label class="check"><input name="yield_confirmed" type="checkbox" ${value.yield_confirmed?'checked':''}><span>Rendimiento confirmado</span></label><label>Observaciones de la receta<textarea name="notes" maxlength="2000">${esc(value.notes)}</textarea></label><div class="work-form-actions"><button type="button" class="secondary" data-dialog-close>Cancelar</button><button>Guardar como provisional</button></div></form>`,onClose:()=>{editing=null;}});}
 async function mutate(action,r,payload,form){const owner=state().user?.id,token=generation;await guard();if(!live(owner,token))return false;if(!navigator.onLine)throw Error('Conéctate a Internet para guardar la receta.');const body=JSON.stringify(payload),holder=form?.dataset;if(holder?.payload!==body){holder&&(holder.request=crypto.randomUUID(),holder.payload=body);}
  const result=await db.rpc('charito_recipe_write',{p_action:action,p_id:r?.id||null,p_version:Number(r?.version||0),p_data:payload,p_request:holder?.request||crypto.randomUUID()});
  if(!live(owner,token))return false;if(result.error)throw Error(result.error.message);dialogs.close(true);await refresh();if(live(owner,token)){render();notice(action==='approve'?'Receta validada.':action==='archive'?'Receta archivada.':'Receta provisional guardada.');}return true;}
 async function click(button){const d=button.dataset;if(!Object.keys(d).some(k=>k.startsWith('recipe')))return false;if(!allowed())throw Error('No tienes acceso al taller.');
  if('recipeNew'in d){if(!editable())throw Error('No puedes editar recetas.');editor(null);return true;}
  if('recipeAdd'in d){const list=button.closest('form').querySelector('[data-recipe-lines]');if(list.children.length>=100)throw Error('El máximo es 100 ingredientes.');list.insertAdjacentHTML('beforeend',ingredient());return true;}
  if('recipeRemove'in d){if(button.closest('[data-recipe-lines]').children.length<=1)throw Error('Conserva al menos un ingrediente.');button.closest('[data-recipe-line]').remove();return true;}
  const id=d.recipeOpen||d.recipeEdit||d.recipeApprove||d.recipeArchive,r=selected(id);if(!r)throw Error('Actualiza la lista de recetas.');
  if('recipeOpen'in d){open(r);return true;}if('recipeEdit'in d){if(!editable())throw Error('No puedes editar recetas.');editor(r);return true;}
  if('recipeApprove'in d||'recipeArchive'in d){if(!approver())throw Error('Solo administración y gerencia pueden aprobar o archivar.');const action='recipeApprove'in d?'approve':'archive';if(!window.confirm(action==='approve'?'¿Validar las cantidades, unidades y el rendimiento de esta receta?':'¿Archivar esta receta?'))return true;button.disabled=true;try{await mutate(action,r,{},button);}finally{button.disabled=false;}return true;}return false;}
 async function submit(action,form){if(action!=='recipe_save')return false;if(!editable())throw Error('No puedes editar recetas.');const id=form.dataset.id,r=id?{id,version:Number(form.dataset.version)}:null;await mutate('save',r,recipePayload(form),form);return true;}
 function input(event){const t=event.target;if(t.hasAttribute('data-recipe-search')||t.hasAttribute('data-recipe-filter')){if(t.hasAttribute('data-recipe-search'))query=t.value;else filter=t.value;const grid=root.querySelector('[data-recipe-grid]');if(grid)grid.innerHTML=cards();}
  if(t.hasAttribute('data-recipe-batches')){const r=selected(t.dataset.recipeId),box=t.closest('.recipe-detail');if(!r||!box)return;try{const scaled=scaleIngredients(lines(r),t.value);t.setCustomValidity('');scaled.forEach((i,n)=>{box.querySelector(`[data-scaled="${n}"]`).textContent=`${number.format(i.required)} ${i.unit}`;});box.querySelector('[data-recipe-calculation]').textContent=`Insumos para ${number.format(t.value)} ${Number(t.value)===1?'tanda':'tandas'}`;}catch(e){t.setCustomValidity(e.message);box.querySelectorAll('[data-scaled]').forEach(el=>el.textContent='—');box.querySelector('[data-recipe-calculation]').textContent=e.message;}}}
 function clear(){generation++;records=[];loaded=false;loading=false;currentOwner='';error='';query='';filter='active';editing=null;loadedAt=0;}
 return {view,enter,click,submit,input,clear};
}
